def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    for c in range(w):
        if all(grid[r][c]==2 for r in range(h)):
            obj=[j for r in range(h) for j in range(w) if grid[r][j] not in (bg,2)]
            if obj:
                edge=max(obj) if min(obj)>c else min(obj)
                target=edge+1 if edge>c else edge-1
                if 0<=target<w:
                    for r in range(h): out[r][target]=8
            return out
    return out
